"""Request syntax and aggregate resource-domain validation.

The reader is deliberately strict: every documented envelope, shape, bound and
aggregate rule is enforced before any offline work starts, so a rejected request
can never emit a partial certificate.
"""
import json
import re

ID = re.compile(r'[A-Za-z0-9_-]{1,32}\Z')
MAX_BYTES = 64 * 1024 ** 2
# Valid requests need at most ~284000 containers (rows, blocks, operations);
# a bracket byte inside any legal string value is impossible, so a larger raw
# structural count can never belong to a valid request.
MAX_CONTAINERS = 300000
PADDING = 1514
OP_LENGTH = {'install': 2, 'open': 2, 'close': 2, 'packet': 5}
RELEASE_FIELDS = ('id classes width eps ratio threshold mode packet_limit '
                  'idle_us discovery train validation')


def require(condition):
    if not condition:
        raise ValueError('invalid_request')


def integer(value, lo, hi):
    return type(value) is int and lo <= value <= hi


def identifier(value):
    return type(value) is str and ID.fullmatch(value) is not None


def keys(obj, fields):
    return type(obj) is dict and set(obj) == set(fields.split())


def fraction(value, max_num=1000000):
    return (type(value) is list and len(value) == 2 and
            integer(value[0], 0, max_num) and integer(value[1], 1, 1000000))


def unique(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result)
        result[key] = value
    return result


def constant(_):
    raise ValueError('nonfinite JSON constant')


def real_values(values):
    """Real (non padding) prefix of an encoded value row."""
    try:
        return values[:values.index(PADDING)]
    except ValueError:
        return values


def real_length(values):
    try:
        return values.index(PADDING)
    except ValueError:
        return len(values)


def _check_values(values, minimum):
    require(type(values) is list and minimum <= len(values) <= 128)
    padding = False
    total = 0
    for value in values:
        require(integer(value, 0, 3028))
        total += 1
        if value == PADDING:
            padding = True
        elif padding:
            require(False)
    return total


def _validate_release(model, totals):
    require(keys(model, RELEASE_FIELDS))
    require(identifier(model['id']))
    require(integer(model['classes'], 1, 16))
    require(integer(model['width'], 2, 16))
    require(fraction(model['eps']) and fraction(model['ratio']))
    require(model['ratio'][0] <= model['ratio'][1])
    require(fraction(model['threshold']))
    require(type(model['mode']) is str and model['mode'] in ('range', 'exact'))
    require(integer(model['packet_limit'], model['width'], 200000))
    require(integer(model['idle_us'], 0, 10 ** 12))
    for group in ('discovery', 'train', 'validation'):
        rows = model[group]
        require(type(rows) is list)
        totals[group] += len(rows)
        labels = set()
        for row in rows:
            discovery = group == 'discovery'
            require(keys(row, 'class values activation' if discovery else 'class values'))
            require(integer(row['class'], 0, model['classes'] - 1))
            labels.add(row['class'])
            totals['values'] += _check_values(row['values'], 2 if discovery else 0)
            if discovery:
                activation = row['activation']
                require(type(activation) is list and len(activation) == len(row['values']))
                for score in activation:
                    require(integer(score, 0, 1000000))
        if group != 'discovery':
            require(labels == set(range(model['classes'])))
    return model['id']


def _validate_operation(event, models, totals):
    require(type(event) is list and len(event) >= 2 and type(event[0]) is str)
    op = event[0]
    require(op in OP_LENGTH and len(event) == OP_LENGTH[op] and identifier(event[1]))
    totals['ops'] += 1
    if op in ('install', 'open', 'packet'):
        totals[op] += 1
    if op == 'install':
        require(event[1] in models)
    if op == 'packet':
        require(integer(event[2], 0, 10 ** 12))
        require(integer(event[3], 0, 1))
        require(integer(event[4], 1, 1514))


def _bounded_depth(root):
    stack = [(root, 1)]
    while stack:
        node, depth = stack.pop()
        if type(node) in (dict, list):
            require(depth <= 32)
            stack.extend((child, depth + 1) for child in
                         (node.values() if type(node) is dict else node))


def validate(root):
    _bounded_depth(root)
    require(keys(root, 'capacity releases blocks'))
    require(keys(root['capacity'], 'range exact'))
    require(integer(root['capacity']['range'], 0, 4096))
    require(integer(root['capacity']['exact'], 0, 8192))
    releases = root['releases']
    require(type(releases) is list and 1 <= len(releases) <= 8)
    blocks = root['blocks']
    require(type(blocks) is list and len(blocks) <= 20000)
    totals = {'discovery': 0, 'train': 0, 'validation': 0, 'values': 0,
              'packet': 0, 'open': 0, 'install': 0, 'ops': 0}
    models = {}
    for model in releases:
        release_id = _validate_release(model, totals)
        require(release_id not in models)
        models[release_id] = model
    require(totals['discovery'] <= 4096)
    require(totals['train'] <= 8192 and totals['validation'] <= 8192)
    require(totals['values'] <= 1048576)
    for block in blocks:
        require(type(block) is list)
        for event in block:
            _validate_operation(event, models, totals)
    require(totals['ops'] <= 218432)
    require(totals['packet'] <= 200000 and totals['open'] <= 8192 and totals['install'] <= 2048)
    return root


def read_request(stream):
    data = stream.read(MAX_BYTES + 1)
    require(len(data) <= MAX_BYTES)
    require(data.count(b'[') + data.count(b'{') <= MAX_CONTAINERS)
    text = data.decode('utf-8')
    root = json.loads(text, object_pairs_hook=unique,
                      parse_constant=constant, parse_float=constant)
    return validate(root)
